class Argument { public required string Text { get; init; } public int Number { get; set; } }
class C {
    public string Text { get; }
    public C(int n) : this(new Argument { Text = "argument", Number = n + 1 }) { Print("outer body"); }
    private C(Argument arg) { Text = arg.Text; Print(arg.Number); }
}
void Main() { Print(new C(4).Text); }
